[ExtensionOf(classStr(PrintMgmtNode_Invent))]
internal final class MetPrintMgmtNode_Invent_Extension
{
}

Method.Source:
    /// <summary>
    /// added more option to printmgmt
    /// </summary>
    /// <returns>list</returns>
    public List getDocumentTypes()
    {
        List docTypes = next getDocumentTypes();

        docTypes.addEnd(PrintMgmtDocumentType::MetCoverNote);
        docTypes.addEnd(PrintMgmtDocumentType::MetContinuousPermissionNotice);
        docTypes.addEnd(PrintMgmtDocumentType::MetDangerousGoodsManifest);

        return docTypes;

    }
